    pub(crate) fn compare_rte_event(
        &self,
        other: &Document,
        a: &RTEEvent,
        b: &RTEEvent,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_structure_element(other, a.base(), b.base(), path)?;
        self.compare_abstract_event(other, a.abstract_event(), b.abstract_event(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_disabled_mode_i_refs();
        let list_b = b.get_disabled_mode_i_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DISABLED_MODE_I_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .r_mode_in_atomic_swc_instance_refs
                .get(*x)
                .ok_or_else(|| {
                    format!("{path}.DISABLED_MODE_I_REFS[{index}]: id not found in own arena")
                })?;
            let y = other
                .r_mode_in_atomic_swc_instance_refs
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.DISABLED_MODE_I_REFS[{index}]: id not found in other arena")
                })?;
            self.compare_r_mode_in_atomic_swc_instance_ref(
                other,
                x,
                y,
                &format!("{path}.DISABLED_MODE_I_REFS[{index}]"),
            )?;
        }
        if a.get_start_on_event_ref() != b.get_start_on_event_ref() {
            return Err(format!("{path}: START_ON_EVENT_REF mismatch"));
        }
        Ok(())
    }

