    pub(crate) fn compare_swc_mode_switch_event(
        &self,
        other: &Document,
        a: &SwcModeSwitchEvent,
        b: &SwcModeSwitchEvent,
        path: &str,
    ) -> Result<(), String> {
        self.compare_rte_event(other, a.base(), b.base(), path)?;
        if a.get_activation() != b.get_activation() {
            return Err(format!("{path}: ACTIVATION mismatch"));
        }
        let list_a = a.get_mode_i_refs();
        let list_b = b.get_mode_i_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MODE_I_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .r_mode_in_atomic_swc_instance_refs
                .get(*x)
                .ok_or_else(|| format!("{path}.MODE_I_REFS[{index}]: id not found in own arena"))?;
            let y = other
                .r_mode_in_atomic_swc_instance_refs
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.MODE_I_REFS[{index}]: id not found in other arena")
                })?;
            self.compare_r_mode_in_atomic_swc_instance_ref(
                other,
                x,
                y,
                &format!("{path}.MODE_I_REFS[{index}]"),
            )?;
        }
        Ok(())
    }

